using System.Security.Claims; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore; using RaceDay.Api.Data; using RaceDay.Api.DTOs; using RaceDay.Api.Models;
namespace RaceDay.Api.Controllers;
[ApiController,Route("api/events")]
public class EventsController(RaceDayDbContext db):ControllerBase {
 int UserId=>int.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 [HttpGet,AllowAnonymous] public async Task<IActionResult> Get([FromQuery]string? search,[FromQuery]DateTime? from)=>Ok(await db.Events.Include(e=>e.EventType).Include(e=>e.Categories).Where(e=>(search==null||e.Name.Contains(search)||e.Location.Contains(search))&&(from==null||e.EventDate>=from)).OrderBy(e=>e.EventDate).Select(e=>new{e.EventId,e.Name,e.Description,e.EventDate,e.Location,e.DistanceKm,EventType=e.EventType!.Name,e.OrganiserId,Categories=e.Categories.Select(c=>new{c.CategoryId,c.Name,c.CategoryType,c.DistanceKm,c.MinimumAge,c.MaximumAge})}).ToListAsync());
 [HttpGet("{id:int}"),AllowAnonymous] public async Task<IActionResult> GetById(int id){var e=await db.Events.Include(x=>x.EventType).Include(x=>x.Categories).Where(x=>x.EventId==id).Select(x=>new{x.EventId,x.Name,x.Description,x.EventDate,x.Location,x.DistanceKm,EventType=x.EventType!.Name,x.OrganiserId,Categories=x.Categories}).FirstOrDefaultAsync();return e==null?NotFound():Ok(e);}
 [Authorize(Roles=Roles.Organiser),HttpPost] public async Task<IActionResult> Create(EventRequest r){if(!await db.EventTypes.AnyAsync(x=>x.EventTypeId==r.EventTypeId))return BadRequest(new{message="Invalid event type."});var e=new Event{Name=r.Name.Trim(),Description=r.Description,EventDate=r.EventDate,Location=r.Location.Trim(),DistanceKm=r.DistanceKm,EventTypeId=r.EventTypeId,OrganiserId=UserId};db.Events.Add(e);await db.SaveChangesAsync();return CreatedAtAction(nameof(GetById),new{id=e.EventId},e);}
 [Authorize(Roles=Roles.Organiser),HttpPut("{id:int}")] public async Task<IActionResult> Update(int id,EventRequest r){var e=await db.Events.FindAsync(id);if(e==null)return NotFound();if(e.OrganiserId!=UserId)return Forbid();if(!await db.EventTypes.AnyAsync(x=>x.EventTypeId==r.EventTypeId))return BadRequest(new{message="Invalid event type."});e.Name=r.Name.Trim();e.Description=r.Description;e.EventDate=r.EventDate;e.Location=r.Location.Trim();e.DistanceKm=r.DistanceKm;e.EventTypeId=r.EventTypeId;await db.SaveChangesAsync();return Ok(e);}
 [Authorize(Roles=Roles.Organiser),HttpDelete("{id:int}")] public async Task<IActionResult> Delete(int id){var e=await db.Events.Include(x=>x.Categories).ThenInclude(c=>c.Enrolments).FirstOrDefaultAsync(x=>x.EventId==id);if(e==null)return NotFound();if(e.OrganiserId!=UserId)return Forbid();if(e.Categories.Any(c=>c.Enrolments.Any()))return Conflict(new{message="Cannot delete an event with enrolments."});db.Events.Remove(e);await db.SaveChangesAsync();return NoContent();}
}
